import 'package:flutter_test/flutter_test.dart';import 'package:mobile_dikasa/core/network/mock_cash_sessions.dart';
void main(){test('mock movements share closing balance and immutable replay',(){final m=MockCashSessions([],()=>[]);final id=m.open(100000)['id'] as String;final a=m.movementCreate(id,{'request_id':'a','kind':'out','name':'Bank','amount':80000,'reason':'Deposit'});expect(m.movementActivity(id,1)['data']['totals']['expected_cash'],20000);expect(m.movementCreate(id,{'request_id':'a','kind':'out','name':'Bank','amount':80000,'reason':'Deposit'})['id'],a['id']);m.movementReverse(id,a['id'],{'request_id':'r','reason':'Wrong'});expect(m.movementActivity(id,1)['data']['totals']['expected_cash'],100000);expect(()=>m.movementReverse(id,a['id'],{'request_id':'r2','reason':'Again'}),throwsA(isA<MockCashError>()));});}
